// Every request must carry the shared secret from WEBHOOK_SECRET: in the X-Webhook-Secret header, or as the
// custom data key webhook_secret (GoHighLevel's standard Webhook action cannot set headers).
// An empty WEBHOOK_SECRET rejects everything, so a missing setting never leaves the door open.
const expected = String($env.WEBHOOK_SECRET || '');
const req = $input.first().json;
const fromHeader = req.headers?.['x-webhook-secret'];
const fromBody = req.body?.customData?.webhook_secret;
const given = typeof fromHeader === 'string' && fromHeader ? fromHeader : (typeof fromBody === 'string' ? fromBody : '');

// Constant time comparison, so the response time does not reveal how much of a guess was right.
function sameSecret(a, b) {
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}
const secretOk = expected.length > 0 && given.length > 0 && sameSecret(given, expected);
return [{ json: { secretOk, secretSource: secretOk ? (given === fromHeader ? 'header' : 'customData') : 'none' }, pairedItem: { item: 0 } }];

// Dates are calendar days (YYYY-MM-DD). Due dates are sent to ClickUp as noon in the business time zone,
// so the day shown is the same for everyone within 11 hours of that zone.
const utcNoon = ymd => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d, 12)); };
const isRealDate = ymd => /^\d{4}-\d{2}-\d{2}$/.test(ymd) && utcNoon(ymd).toISOString().slice(0, 10) === ymd;
const isWeekend = ymd => [0, 6].includes(utcNoon(ymd).getUTCDay());
function addBusinessDays(ymd, n) {
  const d = utcNoon(ymd);
  const step = n < 0 ? -1 : 1;
  for (let left = Math.abs(n); left > 0;) {
    d.setUTCDate(d.getUTCDate() + step);
    if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) left--;
  }
  return d.toISOString().slice(0, 10);
}
function partsIn(tz, date) {
  return Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: tz, hourCycle: 'h23', year: 'numeric', month: '2-digit',
    day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).formatToParts(date).map(p => [p.type, p.value]));
}
function todayIn(tz) { const p = partsIn(tz, new Date()); return `${p.year}-${p.month}-${p.day}`; }
function noonMs(ymd, tz) {
  const guess = utcNoon(ymd).getTime();
  const p = partsIn(tz, new Date(guess));
  const local = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second);
  return guess - (local - guess);
}
const shortDate = ymd => new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }).format(utcNoon(ymd));
const longDate = ymd => new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(utcNoon(ymd));

// Reads the webhook as one clean deal, whatever CRM sent it, and checks this workflow's settings.
// Two shapes are understood: the generic JSON from the README, and the payload of GoHighLevel's workflow
// Webhook action when the trigger is "Opportunity Status Changed" (contact fields, opportunity fields, customData).
const req = $('Deal Webhook').first().json;
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : {};
const text = (v, max = 200) => (v === undefined || v === null ? '' : String(v)).replace(/\s+/g, ' ').trim().slice(0, max);
const WON = ['won', 'closed won', 'closed_won', 'closedwon'];

// The generic shape wins when deal_id or client_name is present. ("pipleline_stage" is GoHighLevel's own spelling.)
const isGhl = !('deal_id' in body || 'client_name' in body) &&
  ['opportunity_name', 'pipleline_stage', 'pipeline_id', 'contact_id'].some(k => k in body);
const custom = body.customData && typeof body.customData === 'object' ? body.customData : {};
const raw = isGhl ? {
  source: 'GoHighLevel',
  dealId: body.id || custom.deal_id,               // the opportunity id
  status: body.status,
  clientName: body.company_name || body.full_name || body.opportunity_name,
  contactName: body.full_name || [body.first_name, body.last_name].filter(Boolean).join(' '),
  email: body.email,
  package: custom.package,
  value: body.lead_value ?? custom.deal_value,
  currency: custom.currency,
  startDate: custom.start_date,
} : {
  source: text(body.source, 60) || 'a CRM webhook',
  dealId: body.deal_id ?? body.id,
  status: body.status ?? body.stage,
  clientName: body.client_name ?? body.company,
  contactName: body.contact_name,
  email: body.contact_email ?? body.email,
  package: body.package,
  value: body.deal_value ?? body.value ?? body.amount,
  currency: body.currency,
  startDate: body.start_date,
};

const status = text(raw.status, 40).toLowerCase();
if (!WON.includes(status)) {
  return [{ json: { valid: true, won: false, status, source: raw.source, deal: { id: text(raw.dealId, 64) } }, pairedItem: { item: 0 } }];
}

// Settings first: a broken setting affects every deal.
const cfgErrors = [];
const required = {
  CLICKUP_API_TOKEN: $env.CLICKUP_API_TOKEN, CLICKUP_WORKSPACE_ID: $env.CLICKUP_WORKSPACE_ID, CLICKUP_TEMPLATE_ID: $env.CLICKUP_TEMPLATE_ID,
  POSTMARK_SERVER_TOKEN: $env.POSTMARK_SERVER_TOKEN, POSTMARK_FROM: $env.POSTMARK_FROM, SLACK_WEBHOOK_URL: $env.SLACK_WEBHOOK_URL,
};
for (const [key, value] of Object.entries(required)) if (!text(value)) cfgErrors.push(`${key} is not set`);
if (!text($env.CLICKUP_SPACE_ID) && !text($env.CLICKUP_FOLDER_ID)) cfgErrors.push('set CLICKUP_SPACE_ID or CLICKUP_FOLDER_ID');
if (text($env.CLICKUP_TEMPLATE_ID) && !/^t-\S+$/.test(text($env.CLICKUP_TEMPLATE_ID))) cfgErrors.push('CLICKUP_TEMPLATE_ID must start with "t-"');
const tz = text($env.BUSINESS_TIMEZONE, 60) || 'UTC';
try { new Intl.DateTimeFormat('en-US', { timeZone: tz }).format(new Date()); } catch (e) { cfgErrors.push(`BUSINESS_TIMEZONE "${tz}" is not a time zone`); }
const defaultDays = Number(text($env.DEFAULT_START_BUSINESS_DAYS) || 5);
if (!Number.isInteger(defaultDays) || defaultDays < 0 || defaultDays > 60) cfgErrors.push('DEFAULT_START_BUSINESS_DAYS must be a whole number from 0 to 60');

let taskCfg = [];
// The .env example wraps the JSON in single quotes. Docker Compose removes them, "docker run --env-file" does not,
// so one pair of surrounding single quotes is accepted here.
let tasksRaw = String($env.KICKOFF_TASKS_JSON || '').trim();
if (tasksRaw.length > 1 && tasksRaw.startsWith("'") && tasksRaw.endsWith("'")) tasksRaw = tasksRaw.slice(1, -1).trim();
try { taskCfg = JSON.parse(tasksRaw); } catch (e) { cfgErrors.push('KICKOFF_TASKS_JSON is not valid JSON'); }
if (!Array.isArray(taskCfg) || taskCfg.length < 1 || taskCfg.length > 25) { cfgErrors.push('KICKOFF_TASKS_JSON must be a list of 1 to 25 tasks'); taskCfg = []; }
const seen = new Set();
taskCfg.forEach((t, i) => {
  const where = `KICKOFF_TASKS_JSON task ${i + 1}`;
  if (!t || typeof t !== 'object' || !text(t.name)) return cfgErrors.push(`${where} has no name`);
  const key = text(t.name).toLowerCase();
  if (seen.has(key)) cfgErrors.push(`${where}: the name "${text(t.name)}" is used twice`);
  seen.add(key);
  if (t.offset_days !== undefined && (!Number.isInteger(t.offset_days) || Math.abs(t.offset_days) > 120)) cfgErrors.push(`${where}: offset_days must be a whole number`);
  if (t.assignees !== undefined && (!Array.isArray(t.assignees) || !t.assignees.every(a => Number.isInteger(a) && a > 0))) cfgErrors.push(`${where}: assignees must be a list of ClickUp user ids (numbers)`);
  if (t.priority !== undefined && t.priority !== null && ![1, 2, 3, 4].includes(t.priority)) cfgErrors.push(`${where}: priority must be 1, 2, 3 or 4`);
});

// Then the deal itself.
const errors = [], warnings = [];
const dealId = text(raw.dealId, 64).replace(/[\[\]]/g, '');
if (!dealId) errors.push('deal_id is missing');
const clientName = text(raw.clientName, 120);
if (!clientName) errors.push('client_name is missing');

if (cfgErrors.length || errors.length) {
  const config = cfgErrors.length > 0;
  return [{ json: {
    valid: false, won: true, deal: { id: dealId, clientName },
    response: config
      ? { code: 500, body: { error: 'This workflow is not configured correctly. The details are in the n8n execution.' } }
      : { code: 400, body: { error: 'The won deal could not be read.', details: errors } },
    stopMessage: `Won deal ${dealId || '(no id)'}${clientName ? ' for ' + clientName : ''} was not processed. ` +
      (config ? `Fix these settings: ${cfgErrors.join('; ')}.` : '') + (errors.length ? ` The payload has problems: ${errors.join('; ')}.` : ''),
  }, pairedItem: { item: 0 } }];
}

const contactName = text(raw.contactName, 120);
let email = text(raw.email, 254).toLowerCase();
if (email && !/^[^\s@<>,;"]+@[^\s@<>,;"]+\.[a-z]{2,}$/i.test(email)) { warnings.push(`"${email}" is not a valid email address`); email = ''; }
let value = null;
if (raw.value !== undefined && raw.value !== null && raw.value !== '') {
  const n = typeof raw.value === 'number' ? raw.value : Number(String(raw.value).replace(/[^0-9.\-]/g, ''));
  if (Number.isFinite(n) && String(raw.value).match(/\d/)) value = Math.round(n * 100) / 100;
  else warnings.push(`Deal value "${text(raw.value, 40)}" is not a number, so it was left out`);
}
const currency = /^[A-Za-z]{3}$/.test(text(raw.currency)) ? text(raw.currency).toUpperCase() : (text($env.DEFAULT_CURRENCY) || 'USD').toUpperCase();
let valueLabel = '';
if (value !== null) { try { valueLabel = new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(value); } catch (e) { valueLabel = `${value} ${currency}`; } }

const today = todayIn(tz);
let startYmd = text(raw.startDate, 40).slice(0, 10);
if (!startYmd || !isRealDate(startYmd)) {
  const given = startYmd;
  startYmd = addBusinessDays(today, defaultDays);
  warnings.push(given ? `Start date "${given}" could not be read, so it was set to ${shortDate(startYmd)}`
                      : `No start date on the deal, so it was set to ${shortDate(startYmd)} (${defaultDays} business days from today)`);
}

// Every due date lands on a business day. Offsets other than 0 already skip weekends; a task on the start date
// itself (offset 0) can still fall on a weekend when the CRM sends a Saturday or Sunday start, and a date that has
// passed moves to today, which can be a weekend day too. Both then move on to the next business day.
const tasks = taskCfg.map(t => {
  const planned = addBusinessDays(startYmd, t.offset_days || 0);
  let dueYmd = planned, why = '';
  if (dueYmd < today) { dueYmd = today; why = 'which has passed'; }
  if (isWeekend(dueYmd)) { dueYmd = addBusinessDays(dueYmd, 1); why = why || 'which is on a weekend'; }
  if (why) warnings.push(`"${text(t.name)}" would have been due ${shortDate(planned)}, ${why}, so it is due ${dueYmd === today ? 'today' : shortDate(dueYmd)}`);
  return {
    name: text(t.name), offsetDays: t.offset_days || 0, assignees: t.assignees || [], priority: t.priority || null,
    description: text(t.description, 2000), inEmail: t.in_email === true, emailLabel: text(t.email_label) || text(t.name),
    dueYmd, dueMs: noonMs(dueYmd, tz), dueLabel: shortDate(dueYmd), dueLong: longDate(dueYmd),
  };
});

const deal = {
  id: dealId, source: raw.source, clientName, contactName, firstName: contactName.split(' ')[0] || '', email,
  package: text(raw.package, 100), value, currency, valueLabel,
  startYmd, startMs: noonMs(startYmd, tz), startLabel: shortDate(startYmd), startLong: longDate(startYmd),
  listName: `${clientName} Onboarding [${dealId}]`, tasks,
};
deal.listContent = `Client onboarding for ${clientName}. Won deal ${dealId} (from ${deal.source}). Package: ${deal.package || 'not given'}. ` +
  `Value: ${valueLabel || 'not given'}. Start: ${deal.startLong}. Contact: ${contactName || 'not given'}${email ? ' (' + email + ')' : ''}.`;

const config = {
  workspaceId: text($env.CLICKUP_WORKSPACE_ID), timezone: tz,
  businessName: text($env.BUSINESS_NAME, 100), bookingUrl: text($env.KICKOFF_BOOKING_URL, 500),
  from: text($env.POSTMARK_FROM, 200), replyTo: text($env.POSTMARK_REPLY_TO, 200), messageStream: text($env.POSTMARK_MESSAGE_STREAM, 60) || 'outbound',
  fields: { package: text($env.CLICKUP_FIELD_PACKAGE) || 'Package', startDate: text($env.CLICKUP_FIELD_START_DATE) || 'Start Date',
            dealValue: text($env.CLICKUP_FIELD_DEAL_VALUE) || 'Deal Value' },
};
return [{ json: { valid: true, won: true, status, source: deal.source, deal, config, warnings }, pairedItem: { item: 0 } }];

// Decides what this webhook needs, from the deal's record in static data:
//   create        a new won deal
//   resume_setup  a list exists but its setup did not finish last time: finish it on the same list
//   resume_email  the setup finished but the welcome email did not go out: send only the email
//   duplicate     already done: do nothing
const n = $input.first().json;
const store = $getWorkflowStaticData('global');
// Own properties only: a deal id like "constructor" must not find Object.prototype.constructor.
const deals = store.deals;
const rec = n.won && deals && Object.prototype.hasOwnProperty.call(deals, n.deal.id) ? deals[n.deal.id] : undefined;

let action;
if (!n.won) action = 'ignore';
else if (!rec) action = 'create';
else if (rec.status === 'setup_incomplete' && rec.listId) action = 'resume_setup';
else if (rec.status === 'email_pending' && n.deal.email) action = 'resume_email';
else action = 'duplicate';

const response = action === 'ignore'
  ? { code: 200, body: { status: 'ignored', reason: n.status ? `status is "${n.status}", only won deals start onboarding` : 'no status in the payload', deal_id: n.deal.id } }
  : action === 'duplicate'
    ? { code: 200, body: { status: 'duplicate', deal_id: n.deal.id, list_url: rec.listUrl || '' } }
    : { code: 202, body: { status: 'accepted', deal_id: n.deal.id, action } };
// "complete" lets an email only retry pass the Setup Complete? check: its setup finished on an earlier run.
return [{ json: { ...n, action, record: rec || null, response, complete: action === 'resume_email' }, pairedItem: { item: 0 } }];

// One record per deal in this workflow's static data. n8n saves it at the end of every production run.
// Records are read and written as own properties only, so a deal id like "constructor" or "__proto__"
// is an ordinary key and never an inherited object property.
const ownRecord = (deals, id) => (deals && Object.prototype.hasOwnProperty.call(deals, id) ? deals[id] : undefined);
function writeDeals(store, entries) {
  // Keep it small: forget deals nobody touched for 400 days, and keep at most 5,000.
  const cutoff = Date.now() - 400 * 864e5;
  store.deals = Object.fromEntries(entries
    .filter(([, r]) => new Date(r.updatedAt).getTime() > cutoff)
    .sort((a, b) => String(b[1].updatedAt).localeCompare(String(a[1].updatedAt)))
    .slice(0, 5000));
}
// A key patched to undefined is removed, so a finished deal does not keep data only a retry needed.
function saveRecord(dealId, patch) {
  const store = $getWorkflowStaticData('global');
  const others = Object.entries(store.deals || {}).filter(([k]) => k !== dealId);
  const rec = { ...(ownRecord(store.deals, dealId) || {}), ...patch, updatedAt: new Date().toISOString() };
  for (const k of Object.keys(rec)) if (rec[k] === undefined) delete rec[k];
  writeDeals(store, [...others, [dealId, rec]]);
}
function forgetRecord(dealId) {
  const store = $getWorkflowStaticData('global');
  writeDeals(store, Object.entries(store.deals || {}).filter(([k]) => k !== dealId));
}

// ClickUp already has a list with this deal id in its name (made by an earlier run, or by hand).
// Nothing is created and no email is sent. The deal is remembered, so the next copy stops even earlier.
const ctx = $('Check Deal State').first().json;
const tag = '[' + ctx.deal.id + ']';
const list = ($('ClickUp: Find Existing List').first().json.lists || []).find(l => String(l.name || '').includes(tag));
const listUrl = `https://app.clickup.com/${ctx.config.workspaceId}/v/li/${list.id}`;
saveRecord(ctx.deal.id, { status: 'done', adopted: true, listId: String(list.id), listUrl, listName: list.name });
return [{ json: { report: { outcome: 'adopted', deal: ctx.deal, listId: String(list.id), listUrl, listName: list.name, warnings: [] } }, pairedItem: { item: 0 } }];

// Turns an n8n HTTP error into one short line, for example "401 Token invalid (OAUTH_025)".
// n8n puts the HTTP status in error.status and the response body in the message: 401 - "{\"err\":...}".
// With pagination on, the status is in error.statusCode or error.response.status instead.
// A timeout has no status, only code ECONNABORTED.
function errorStatus(e) {
  if (!e || typeof e !== 'object') return 0;
  const s = Number(e.status || e.httpCode || e.statusCode || e.response?.status || (String(e.message || '').match(/^(\d{3}) - /) || [])[1] || 0);
  return Number.isFinite(s) ? s : 0;
}
// The API's own answer (ClickUp: {err, ECODE}, Postmark: {ErrorCode, Message}), parsed from wherever n8n put it.
function errorBody(e) {
  if (!e || typeof e !== 'object') return undefined;
  let body = e.error ?? e.response?.body;
  const quoted = String(e.message || '').match(/^\d{3} - ("[\s\S]*")$/);
  if (body === undefined && quoted) { try { body = JSON.parse(quoted[1]); } catch (x) {} }
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (x) {} }
  return body;
}
function describeError(e) {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 300);
  const status = errorStatus(e);
  const msg = String(e.message || '');
  const body = errorBody(e);
  let detail = '';
  if (body && typeof body === 'object') {
    if (body.err) detail = body.err + (body.ECODE ? ' (' + body.ECODE + ')' : '');
    else if (body.Message) detail = body.Message + (body.ErrorCode !== undefined ? ' (Postmark error ' + body.ErrorCode + ')' : '');
    else if (body.message) detail = String(body.message);
  } else if (typeof body === 'string') detail = body.trim();
  if (!detail) detail = e.code === 'ECONNABORTED' ? `no answer in time (${msg})` : (msg || e.code || 'no details');
  return ((status ? status + ' ' : '') + detail).replace(/\s+/g, ' ').trim().slice(0, 300);
}

// The template call failed or timed out. ClickUp keeps building a list from a template past a timeout, and
// it refuses a second list with the same name. So before calling this a failure, look for the list again:
//   recovered  the list exists and our call timed out or got a 5xx: ClickUp made it, carry on with it.
//              Also a 4xx on the second try: that "name taken" is about the list from our own first try.
//   taken      the list exists and our first call got a 4xx (usually "name taken"): another run is setting it up
//   retry      no list, and the first call got no answer or a 5xx: nothing was created, so one more try is safe
//   failed     no list after a 4xx (a wrong id or setting) or after the second try: nothing was created
const ctx = $('Check Deal State').first().json;
const attempt = $runIndex;   // 0 after the first template call, 1 after the retry
let createError;
try { createError = $('ClickUp: Create From Template').itemMatching(0).json.error; } catch (e) {}
const status = errorStatus(createError);
const tag = '[' + ctx.deal.id + ']';
const list = ($input.first().json.lists || []).find(l => String(l.name || '').includes(tag));
const clientSide = status >= 400 && status < 500;
const outcome = list ? (clientSide && attempt === 0 ? 'taken' : 'recovered') : (!clientSide && attempt === 0 ? 'retry' : 'failed');
return [{ json: { outcome, attempt, listId: list ? String(list.id) : '', createError: describeError(createError), createStatus: status }, pairedItem: { item: 0 } }];

// Turns an n8n HTTP error into one short line, for example "401 Token invalid (OAUTH_025)".
// n8n puts the HTTP status in error.status and the response body in the message: 401 - "{\"err\":...}".
// With pagination on, the status is in error.statusCode or error.response.status instead.
// A timeout has no status, only code ECONNABORTED.
function errorStatus(e) {
  if (!e || typeof e !== 'object') return 0;
  const s = Number(e.status || e.httpCode || e.statusCode || e.response?.status || (String(e.message || '').match(/^(\d{3}) - /) || [])[1] || 0);
  return Number.isFinite(s) ? s : 0;
}
// The API's own answer (ClickUp: {err, ECODE}, Postmark: {ErrorCode, Message}), parsed from wherever n8n put it.
function errorBody(e) {
  if (!e || typeof e !== 'object') return undefined;
  let body = e.error ?? e.response?.body;
  const quoted = String(e.message || '').match(/^\d{3} - ("[\s\S]*")$/);
  if (body === undefined && quoted) { try { body = JSON.parse(quoted[1]); } catch (x) {} }
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (x) {} }
  return body;
}
function describeError(e) {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 300);
  const status = errorStatus(e);
  const msg = String(e.message || '');
  const body = errorBody(e);
  let detail = '';
  if (body && typeof body === 'object') {
    if (body.err) detail = body.err + (body.ECODE ? ' (' + body.ECODE + ')' : '');
    else if (body.Message) detail = body.Message + (body.ErrorCode !== undefined ? ' (Postmark error ' + body.ErrorCode + ')' : '');
    else if (body.message) detail = String(body.message);
  } else if (typeof body === 'string') detail = body.trim();
  if (!detail) detail = e.code === 'ECONNABORTED' ? `no answer in time (${msg})` : (msg || e.code || 'no details');
  return ((status ? status + ' ' : '') + detail).replace(/\s+/g, ' ').trim().slice(0, 300);
}

// Nothing was created in ClickUp. Report it with the reason. No welcome email goes out.
const ctx = $('Check Deal State').first().json;
const j = $input.first().json;
let step, error;
if (j.outcome === 'failed') {
  step = 'ClickUp: Create From Template';
  error = j.attempt > 0
    ? `${j.createError}. The call was made twice, and after each try no list for this deal existed.`
    : `${j.createError}. Checked again afterwards: no list for this deal exists.`;
} else if ('lists' in j || 'createError' in j) {
  let first = '';
  try { first = describeError($('ClickUp: Create From Template').itemMatching(0).json.error); } catch (e) {}
  step = 'ClickUp: Find List Again';
  error = `${first ? 'Creating the list failed (' + first + '), then ' : ''}checking for the list failed: ${describeError(j.error)}`;
} else {
  step = 'ClickUp: Find Existing List';
  error = describeError(j.error);
}
return [{ json: { report: { outcome: 'clickup_failed', deal: ctx.deal, step, error, warnings: ctx.warnings || [] } }, pairedItem: { item: 0 } }];

// One record per deal in this workflow's static data. n8n saves it at the end of every production run.
// Records are read and written as own properties only, so a deal id like "constructor" or "__proto__"
// is an ordinary key and never an inherited object property.
const ownRecord = (deals, id) => (deals && Object.prototype.hasOwnProperty.call(deals, id) ? deals[id] : undefined);
function writeDeals(store, entries) {
  // Keep it small: forget deals nobody touched for 400 days, and keep at most 5,000.
  const cutoff = Date.now() - 400 * 864e5;
  store.deals = Object.fromEntries(entries
    .filter(([, r]) => new Date(r.updatedAt).getTime() > cutoff)
    .sort((a, b) => String(b[1].updatedAt).localeCompare(String(a[1].updatedAt)))
    .slice(0, 5000));
}
// A key patched to undefined is removed, so a finished deal does not keep data only a retry needed.
function saveRecord(dealId, patch) {
  const store = $getWorkflowStaticData('global');
