let lines, failed = false, summary;

if (r.outcome === 'ready') {
  failed = r.emailStatus === 'failed';
  const title = r.how === 'email_retry'
    ? (failed ? `:warning: *Welcome email failed again: ${client}*` : `:white_check_mark: *Welcome email sent: ${client}*`)
    : (failed ? `:warning: *Onboarding ready, but the welcome email failed: ${client}*` : `:white_check_mark: *Onboarding ready: ${client}*`);
  lines = [title, facts, link];
  if (r.how === 'recovered') lines.push(':information_source: ClickUp needed longer than the timeout to build the list. The workflow found the list and finished the setup on it.');
  if (r.how === 'retried') lines.push(':information_source: The first call to ClickUp failed and no list had been made, so the workflow tried once more.');
  if (r.how === 'resumed') lines.push(':information_source: Picked up where the last run stopped. Nothing was created twice.');
  if (r.how !== 'email_retry') lines.push('Kickoff tasks:', ...r.tasks.map(taskLine));
  if (r.emailStatus === 'sent') lines.push(`Welcome email sent to ${esc(r.emailTo)}`);
  if (r.emailStatus === 'skipped') lines.push(':warning: No valid email address on the deal, so no welcome email was sent. Add it in the CRM and send the webhook again to send it.');
  if (failed) lines.push(`Email to ${esc(r.emailTo)} failed: ${esc(r.emailError)}`,
    'The ClickUp project is kept. Send the welcome email by hand, or fix the cause and send the same webhook again to retry only the email.');
  summary = failed ? `the ClickUp project is ready but the welcome email failed (${r.emailError})` : 'ready';
} else if (r.outcome === 'partial') {
  failed = true;
  const done = (r.tasks || []).filter(t => t.exists);
  lines = [`:warning: *Onboarding only partly set up: ${client}*`, facts, link];
  if (done.length) lines.push('In the list now:', ...done.map(taskLine));
  lines.push('Failed:', ...r.failures.map(f => `• ${esc(f.label)}: ${esc(f.error)}`));
  lines.push(r.note ? esc(r.note) : 'The welcome email has NOT been sent. Fix the cause, then send the same webhook again: the workflow continues on this list and only does what is missing.');
  summary = `the setup is incomplete (${r.failures.length} change${r.failures.length === 1 ? '' : 's'} failed)`;
} else if (r.outcome === 'clickup_failed') {
  failed = true;
  lines = [`:x: *ClickUp project NOT created: ${client}*`, facts, `Step: ${esc(r.step)}`, `Error: ${esc(r.error)}`,
           'No welcome email was sent. Fix the cause, then send the same webhook again.'];
  summary = `no ClickUp project was created (${r.step}: ${r.error})`;
} else {
  // The list was made by hand, or by a run whose record was lost. It may be half finished, so the team is told
  // what to check instead of the workflow changing a list it did not set up.
  lines = [`:information_source: *A ClickUp list already exists for ${client}*`, facts, link,
           'Nothing was created or changed and no welcome email was sent. This workflow has no record of setting up that list, ' +
           'so check that its kickoff tasks are in place and send the welcome email by hand if the client has not had it.'];
  summary = 'already had a list';
}
const text = [...lines, ...warnings].filter(Boolean).join('\n');
const stopMessage = `Onboarding for ${d.clientName || 'a client'} (deal ${d.id}): ${summary}. The details were posted to Slack.`;
return [{ json: { text, failed, stopMessage }, pairedItem: { item: 0 } }];
